import gurobipy as gp
from gurobipy import GRB
platforms = []
capacities = {}
genres = []
values = {}
requirements = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'resource_id' in v and 'resource_capacity' in v:
        pid = v['resource_id']
        platforms.append(pid)
        capacities[pid] = int(v['resource_capacity'])
    if 'item_name' in v and 'item_value' in v and ('resource_requirement' in v):
        g = v['item_name']
        genres.append(g)
        values[g] = int(v['item_value'])
        requirements[g] = int(v['resource_requirement'])
if len(platforms) == 0 or len(genres) == 0:
    raise ValueError('Missing platforms or genres in LEGACY_RECORDS')
for pid in platforms:
    if pid not in capacities:
        raise ValueError(f'Missing capacity for platform {pid}')
for g in genres:
    if g not in values or g not in requirements:
        raise ValueError(f'Missing value or requirement for genre {g}')
m = gp.Model('game_store_allocation')
x = m.addVars(platforms, genres, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[g] * x[p, g] for p in platforms for g in genres)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((requirements[g] * x[p, g] for g in genres)) <= capacities[p] for p in platforms), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')